{
  "table": {
    "name": "transactions_1k",
    "purpose": "Point-of-sale fuel/shop purchases at gas stations (1,000-row sample of a larger transactions table, per the _1k suffix). Each row records who bought (CustomerID -> customers, plus the CardID used), where (GasStationID -> gasstations), what and how much (ProductID -> products, Amount), when (Date + Time), and the total charged (Price). The companion yearmonth table presumably aggregates dates by month for the full dataset."
  },
  "columns": {
    "Amount": {
      "role": "foreign_key",
      "name": "Quantity purchased",
      "description": "Quantity of the product bought, in the product's natural unit; for the dominant fuel products this is presumably volume in liters (integer, 0-264, median 19), though the unit is not directly evidenced. 91 rows (9.1%) have Amount = 0, likely non-fuel purchases or services with no measured quantity. The detected join to products.ProductID is spurious: Amount's 0-264 range merely overlaps ProductID's 2-352 values; a quantity does not reference a product.",
      "status": "resolved"
    },
    "CardID": {
      "role": "identifier",
      "name": "Card identifier",
      "description": "Identifier of the card used to pay for the transaction (numeric IDs roughly 26,000-776,000). 902 distinct values in 1,000 rows, reused up to 4 times, so it identifies a reusable card rather than a one-off authorization code; with 902 distinct cards vs 517 distinct customers, a customer can apparently use more than one card. No table joins to it, so the card type/issuer (loyalty, fleet, payment) is unconfirmed.",
      "status": "resolved"
    },
    "CustomerID": {
      "role": "foreign_key",
      "name": "Customer identifier",
      "description": "Foreign key to customers.CustomerID; the customer associated with the purchase (517 distinct customers in this sample).",
      "status": "resolved"
    },
    "Date": {
      "role": "date",
      "name": "Transaction date",
      "description": "Calendar date of the transaction, stored as ISO 'YYYY-MM-DD' text. This 1,000-row sample covers only four consecutive days, 2012-08-23 to 2012-08-26 (492 rows on Aug 24, 425 on Aug 25).",
      "status": "resolved"
    },
    "GasStationID": {
      "role": "foreign_key",
      "name": "Gas station identifier",
      "description": "Foreign key to gasstations.GasStationID; the gas station where the transaction took place (437 distinct stations appear in the sample).",
      "status": "resolved"
    },
    "Price": {
      "role": "numeric",
      "name": "Total transaction price",
      "description": "Total monetary amount charged for the transaction, not a unit price: two-decimal values from 1.76 to 5,762.49, and Price/Amount yields an approximately constant per-unit price per product (e.g., 3.64/4 = 0.91; 1,445.97/63 = 22.95; 524.60/24 = 21.86). The currency cannot be determined from the data.",
      "status": "resolved"
    },
    "ProductID": {
      "role": "foreign_key",
      "name": "Product identifier",
      "description": "Foreign key to products.ProductID; the product purchased. 28 distinct products, with IDs 2 and 5 accounting for ~76% of rows, consistent with a couple of dominant fuel grades. No key->label pairs from the products table were provided, so which product each ID denotes is unknown.",
      "status": "resolved"
    },
    "Time": {
      "role": "numeric",
      "name": "Transaction time of day",
      "description": "Time of day of the transaction, stored as 'HH:MM:SS' text; seconds are always 00, so the effective resolution is one minute.",
      "status": "resolved"
    },
    "TransactionID": {
      "role": "identifier",
      "name": "Transaction identifier (surrogate key)",
      "description": "Surrogate primary key for the transaction; unique sequential integers 1-1000, one per row. The detected 'referenced_by' join from gasstations.ChainID is spurious: ChainID is a small station-chain code whose values merely fall inside the 1-1000 range, and a chain code cannot semantically reference individual transactions.",
      "status": "resolved"
    }
  }
}
